autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc06={id="rwnpc06",baseId="rwnpc15",combatid={1,1001},name="上官瑶",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL上官瑶：哼，不如将其拓印下来，各门各派皆存一份，看到届时还有何可争。NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL上官瑶：我听闻箫公子恩师葬于东方，方才还问我天都峰的地形呢，你们往鲫鱼背的方向去，说不定就在那边。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YELYEL武林盟弟子：弟子这就去。NOR"}},{type="gaintab",args={"315008",3}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}},{type="outobject",args={"rwnpc03"}},{type="refresh",args={}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL上官瑶：我听闻箫公子恩师葬于东方，方才还问我天都峰的地形呢，你们往鲫鱼背的方向去，说不定就在那边。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YELYEL武林盟弟子：弟子这就去。NOR"}}},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"315008",2}}}},autoResult1={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc07={id="rwnpc07",baseId="rwnpc03",combatid={1,1001},name="清如水",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"CYN她只瞥了你一眼，什么都没说，便离开了此处。NOR"}},{type="outobject",args={"rwnpc07"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc08={id="rwnpc08",baseId="rwnpc04",combatid={1,1001},name="箫秋山",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL箫秋山：她是我师妹，生来便是这般性情，并无恶意，少侠莫要怪罪。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="outobject",args={"rwnpc07"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="timechoice",args={"你和他才说没两句话，忽然一道暗器向你们袭来。","3",{{"doc",{"CYN暗器来得太快，你没得及反应，还是箫秋山拉了你一下，才将将躲过暗器。NOR"}},{"gaintab",{"315008",6}},{"showbutton",{2,0}},{"showbutton",{3,1}},{"refresh"}},{"击落",{{"doc",{"CYN你反手将暗器击落，一个蒙面人从暗处走了出来。NOR"}},{"gaintab",{"315008",6}},{"showbutton",{2,0}},{"showbutton",{3,1}},{"refresh"}}},{"躲避",{{"doc",{"CYN你身形一闪，避开了暗器，一个蒙面人从暗处走了出来。NOR"}},{"gaintab",{"315008",6}},{"showbutton",{2,0}},{"showbutton",{3,1}},{"refresh"}}}}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL箫秋山：阁下何不以真面目示人？NOR"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL箫秋山：交出原本？痴心妄想。NOR"}}},caozuoName5="交谈",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="doc",args={"YEL箫秋山：少侠放心，只是普通药粉，吓唬他一下罢了。话说回来，多谢少侠出手相助。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL箫秋山：这般情形我也早有预料，只是没想到会来得这么快。罢了，不聊这些。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL箫秋山：少侠方才说平遥公主？我素来听闻公主礼贤下士，早已钦佩多时，我们还是先去拜见公主吧，别让公主久等了。NOR"}},{type="gaintab",args={"315008",10}},{type="gaintab",args={"315009",1}},{type="change",args={"rwnpc08","rwnpc08a"}},{type="refresh",args={}}},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"315008",8}}}},autoResult1={{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"315008",9}}}},autoResult2={{type="showbutton",args={3,0}},{type="showbutton",args={4,0}},{type="showbutton",args={5,1}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},rwnpc08a={id="rwnpc08a",baseId="rwnpc04",combatid={1,1001},name="箫秋山",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="redoc",args={"YEL箫秋山：真假是非，光凭我说是无用的。况且我此次拿出隐脉图，也并非是为了让所有人相信这是真的，信与不信，全看自身罢了。NOR","YEL箫秋山：我的恩师生前一直想将隐脉图名扬于世，他曾想过将隐脉图交于少林武当这些名门大派，却又顾虑重重，怕落入小人手中，又因他素来谨小慎微，迟迟不敢行动，抱憾而终。NOR","YEL箫秋山：恩师曾说天下武功和医术一般，源起于一两人，发于众人，若是一直埋藏，最终会使明珠泯灭于尘。我并非多么大义，只是自知资质不佳，未来难测，恐怕隐脉图会失于我手。如今也只是为了不使明珠蒙尘，为了告慰恩师罢了。NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}